(6201792, 915669, 98339, '<td valign="top">to me it seems that the proportions are off from the moon to the people and a bit of fog/smoke might have softened your people around their feet</td>', 'to me it seems that the proportions are off from the moon to the people and a bit of fog/smoke might have softened your people around their feet', '2010-10-26 15:03:47.000000', NULL, 1),
